/** Chunk loaders by part id, generated by `partom release`. */
export type IChunkLoaders = Readonly<Record<string, () => Promise<unknown>>>

/**
 * Calls, in parallel, the loader of every referenced part that has one and is not loaded yet, and
 * waits for all of them. Loaded ids are added to `loaded` only after every loader succeeded; the
 * first failure rejects.
 */
export async function preloadChunks(
  chunks: IChunkLoaders | undefined,
  definitions: readonly string[],
  loaded: Set<string>
): Promise<void> {
  if (chunks === undefined) return
  /** Ids to load now. */
  const pending = definitions.filter((id) => !loaded.has(id) && Object.hasOwn(chunks, id))
  await Promise.all(pending.map((id) => (chunks[id] as () => Promise<unknown>)()))
  for (const id of pending) loaded.add(id)
}
